def snap():
    a=current_frame.ascii.split('\n'); g=[list(r) for r in a]
    out={}
    for col,name in [('Y','yellow'),('N','green'),('S','sky'),('O','orange'),('G','cap')]:
        cells=[(r,c) for r in range(54) for c in range(64) if g[r][c]==col]
        if not cells: out[name]='none'; continue
        rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
        out[name]=f"{len(cells)}px r{min(rs)}-{max(rs)} c{min(cs)}-{max(cs)}"
    out['dot']=[(r,c) for r in range(54) for c in range(64) if g[r][c]=='r' and not (29<=r<=33 and 50<=c<=54)]
    out['hud']=sum(1 for c in range(64) if g[63][c]=='G')
    return out
