def comps(fr, chars):
    aa = fr.ascii.split('\n')
    g = {r:[aa[r][c] for c in range(64)] for r in range(64)}
    seen=set(); out=[]
    for r in range(64):
        for c in range(64):
            if g[r][c] in chars and (r,c) not in seen:
                col=g[r][c]; st=[(r,c)]; seen.add((r,c)); cl=[]
                while st:
                    x,y=st.pop(); cl.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        q=(x+dx,y+dy)
                        if 0<=q[0]<64 and 0<=q[1]<64 and g[q[0]][q[1]]==col and q not in seen:
                            seen.add(q); st.append(q)
                rs=[p[0] for p in cl]; cs=[p[1] for p in cl]
                out.append((col,min(rs),min(cs),max(rs),max(cs),len(cl)))
    return out
