def bfs4(start, gtest, cap=300000, stepf=None):
    stepf = stepf or step3
    seen={start}; q=deque([(start,[])])
    while q:
        st,p=q.popleft()
        if gtest(st): return p
        for a in ['UP','DOWN','LEFT','RIGHT']:
            ns=stepf(st,a)
            if ns and ns not in seen:
                seen.add(ns); q.append((ns,p+[a]))
                if len(seen)>cap: return 'CAP'
    return None
