def rp(f):
    a=f.ascii.split('\n')
    cells=[(r,c) for r in range(3,32) for c in range(32,62) if a[r][c]=='Y']
    for cl in comp(cells):
        if len(cl)==14:
            r0=min(p[0] for p in cl); c0=min(p[1] for p in cl)
            g=[''.join('#' if (r,c) in set(cl) else '.' for c in range(c0,c0+4)) for r in range(r0,r0+4)]
            return ((r0-4)//4,(c0-33)//4, g[0])
    return None
