def rng(row,ch='S'):
    s=a[row]; out=[];st=None
    for i,c in enumerate(s):
        if c==ch and st is None: st=i
        elif c!=ch and st is not None: out.append((st,i-1));st=None
    if st is not None: out.append((st,63))
    return out
